const payload = msg.payload || {};
const chatId = payload.chatId || payload.chatid || payload.message?.chat?.id;
const text = String(payload.content || payload.text || payload.message?.text || '').trim();

if (!chatId) {
    node.warn('Mensagem sem chatId recebida do Telegram.');
    return null;
}

const sessionKey = `studentSession:${chatId}`;
const aluno = flow.get(sessionKey) || {};

msg.telegramChatId = chatId;
msg.originalText = text;
msg.payload = text || '/start';
msg.params = {
    session_id: String(chatId),
    return_context: true,
    alternate_intents: true
};

msg.additional_context = {
    telegram_chat_id: String(chatId),
    aluno_identificado: aluno.status === 'identified',
    aluno_id: aluno.alunoId || null,
    aluno_nome: aluno.nome || null,
    aluno_cpf: aluno.cpf || null,
    aluno_rm: aluno.rm || null,
    aluno_curso: aluno.curso || null
};

return msg;

const watson = msg.payload || {};
const chatId = msg.telegramChatId || watson.context?.skills?.['main skill']?.user_defined?.telegram_chat_id;
const sessionKey = `studentSession:${chatId}`;
const session = flow.get(sessionKey) || {};

function direct(content) {
    msg.payload = {
        chatId,
        type: 'message',
        content
    };
    return [null, msg];
}

function getUserDefined() {
    return watson.context?.skills?.['main skill']?.user_defined || {};
}

function getAssistantText() {
    const generic = watson.output?.generic || [];
    const texts = generic
        .filter(item => item.response_type === 'text' && item.text)
        .map(item => item.text.trim())
        .filter(Boolean);
    return texts.join('\n\n');
}

function normalize(value) {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .trim();
}

function onlyDigits(value) {
    return String(value || '').replace(/\D/g, '');
}

function sqlQuote(value) {
    return String(value).replace(/'/g, "''");
}

function firstDefined(...values) {
    return values.find(value => value !== undefined && value !== null && String(value).trim() !== '');
}

function entityValue(names) {
    const entities = watson.output?.entities || [];
    for (const entity of entities) {
        const entityName = normalize(entity.entity);
        if (names.map(normalize).includes(entityName)) {
            return entity.value || entity.literal || entity.location?.join(' ');
        }
    }
    return null;
}

function actionFromWatson(userDefined) {
    const raw = firstDefined(
        userDefined.acao_consulta,
        userDefined.acao,
        userDefined.action,
        userDefined.tipo_consulta,
        userDefined.consulta_tipo,
        userDefined.intent
    );
    return normalize(raw).replace(/\s+/g, '_');
}

function canonicalAction(action) {
    const aliases = {
        identificar: 'identificar_aluno',
        identificar_aluno: 'identificar_aluno',
        buscar_aluno: 'identificar_aluno',
        consultar_aluno: 'perfil',
        perfil: 'perfil',
        dados_aluno: 'perfil',
        rm: 'rm',
        consultar_rm: 'rm',
        curso: 'curso',
        consultar_curso: 'curso',
        notas: 'notas',
        consultar_notas: 'notas',
        materia: 'materias',
        materias: 'materias',
        materias_inscritas: 'materias',
        consultar_materias: 'materias',
        faltas: 'faltas',
        consultar_faltas: 'faltas',
        turno: 'turnos',
        turnos: 'turnos',
        consultar_turnos: 'turnos'
    };
    return aliases[action] || '';
}

function identifierFromWatson(userDefined) {
    const cpf = onlyDigits(firstDefined(userDefined.cpf, userDefined.aluno_cpf, entityValue(['cpf'])) || '');
    const rmRaw = firstDefined(userDefined.rm, userDefined.aluno_rm, entityValue(['rm', 'registro_matricula']));
    const rm = rmRaw ? String(rmRaw).replace(/\s+/g, '').toUpperCase() : '';

    if (cpf.length === 11) return { cpf };
    if (rm) return { rm: rm.startsWith('RM') ? rm : `RM${rm}` };
    if (session.alunoId) return { alunoId: session.alunoId };
    return null;
}

function studentWhere(identifier) {
    if (identifier?.cpf) return `a.cpf = '${sqlQuote(identifier.cpf)}'`;
    if (identifier?.rm) return `upper(a.rm) = '${sqlQuote(identifier.rm.toUpperCase())}'`;
    if (identifier?.alunoId) return `a.id = ${Number(identifier.alunoId)}`;
    return null;
}

function buildQuery(action, identifier) {
    const where = studentWhere(identifier);
    if (!where) return null;
    const studentColumns = 'a.id AS aluno_id, a.cpf, a.nome AS aluno_nome, a.rm, c.nome AS curso_nome';

    if (['identificar_aluno', 'perfil', 'rm', 'curso'].includes(action)) {
        return `SELECT ${studentColumns} FROM aluno a JOIN curso c ON c.id = a.curso_id WHERE ${where} LIMIT 1`;
    }

    if (action === 'notas') {
        return `SELECT ${studentColumns}, m.nome AS materia_nome, m.turno, m.total_horas, n.cp_1, n.cp_2, n.gs_1, n.ch_1, n.media_final FROM aluno a JOIN curso c ON c.id = a.curso_id LEFT JOIN notas n ON n.aluno_id = a.id LEFT JOIN materia m ON m.id = n.materia_id WHERE ${where} ORDER BY m.nome`;
    }

    if (action === 'materias') {
        return `SELECT DISTINCT ${studentColumns}, m.nome AS materia_nome, m.turno, m.total_horas FROM aluno a JOIN curso c ON c.id = a.curso_id JOIN aluno_materia am ON am.aluno_id = a.id JOIN materia m ON m.id = am.materia_id WHERE ${where} ORDER BY m.nome`;
    }

    if (action === 'turnos') {
        return `SELECT DISTINCT ${studentColumns}, m.nome AS materia_nome, m.turno FROM aluno a JOIN curso c ON c.id = a.curso_id JOIN aluno_materia am ON am.aluno_id = a.id JOIN materia m ON m.id = am.materia_id WHERE ${where} ORDER BY m.turno, m.nome`;
    }

    if (action === 'faltas') {
        return `SELECT ${studentColumns}, m.nome AS materia_nome, m.turno, m.total_horas, COUNT(am.data_presenca) AS presencas_registradas, max(m.total_horas - COUNT(am.data_presenca), 0) AS faltas_calculadas FROM aluno a JOIN curso c ON c.id = a.curso_id JOIN materia m ON m.curso_id = a.curso_id LEFT JOIN aluno_materia am ON am.aluno_id = a.id AND am.materia_id = m.id WHERE ${where} GROUP BY a.id, m.id ORDER BY m.nome`;
    }

    return null;
}

if (!chatId) {
    node.warn('Watson retornou sem chatId de Telegram.');
    return [null, null];
}

const userDefined = getUserDefined();
const assistantText = getAssistantText();
const action = canonicalAction(actionFromWatson(userDefined));

if (!action) {
    return direct(assistantText || 'Certo. Como posso te ajudar agora?');
}

const identifier = identifierFromWatson(userDefined);
if (!identifier) {
    return direct(assistantText || 'Para consultar seus dados, me informe o CPF ou o RM, por favor.');
}

const topic = buildQuery(action, identifier);
if (!topic) {
    return direct(assistantText || 'Ainda nao consegui entender exatamente qual consulta voce quer fazer.');
}

msg.queryType = action;
msg.identifier = identifier;
msg.assistantText = assistantText;
msg.topic = topic;
return [msg, null];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const queryType = msg.queryType || 'perfil';
const sessionKey = `studentSession:${msg.telegramChatId || msg.payload?.chatId}`;

function maskCpf(value) {
    const cpf = String(value || '').replace(/\D/g, '');
    return cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
}

function reply(content) {
    msg.payload = {
        chatId: msg.telegramChatId,
        type: 'message',
        content
    };
    return msg;
}

function studentNotFound() {
    const id = msg.identifier?.cpf ? maskCpf(msg.identifier.cpf) : msg.identifier?.rm || 'informado';
    return reply(`Nao encontrei nenhum aluno com ${id}. Pode conferir se o CPF ou RM esta certinho e me mandar novamente?`);
}

function sessionFrom(row) {
    return {
        status: 'identified',
        alunoId: row.aluno_id,
        cpf: row.cpf,
        rm: row.rm,
        nome: row.aluno_nome,
        curso: row.curso_nome
    };
}

function header(row) {
    return [
        `Aluno: ${row.aluno_nome}`,
        `CPF: ${maskCpf(row.cpf)}`,
        `RM: ${row.rm}`,
        `Curso: ${row.curso_nome}`
    ];
}

if (rows.length === 0) {
    return studentNotFound();
}

const aluno = rows[0];
flow.set(sessionKey, sessionFrom(aluno));

if (queryType === 'identificar_aluno') {
    return reply([
        `Pronto, encontrei seu cadastro, ${aluno.aluno_nome}.`,
        `Seu RM e ${aluno.rm}.`,
        '',
        'Agora posso te ajudar com curso, notas, materias inscritas, faltas e turnos.'
    ].join('\n'));
}

if (queryType === 'perfil') {
    return reply(header(aluno).join('\n'));
}

if (queryType === 'rm') {
    return reply([`O RM de ${aluno.aluno_nome} e ${aluno.rm}.`, `O CPF cadastrado e ${maskCpf(aluno.cpf)}.`].join('\n'));
}

if (queryType === 'curso') {
    return reply([`O curso de ${aluno.aluno_nome} e ${aluno.curso_nome}.`, `RM: ${aluno.rm}`].join('\n'));
}

if (queryType === 'notas') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) return reply(`Ainda nao encontrei notas cadastradas para ${aluno.aluno_nome}.`);
    const lines = header(aluno).concat('', 'Aqui estao as notas que encontrei:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome}: CP1 ${materia.cp_1}, CP2 ${materia.cp_2}, GS1 ${materia.gs_1}, CH1 ${materia.ch_1}, media ${materia.media_final}`);
    }
    return reply(lines.join('\n'));
}

if (queryType === 'materias') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) return reply(`Nao encontrei materias inscritas para ${aluno.aluno_nome}.`);
    const lines = header(aluno).concat('', 'Estas sao as materias inscritas:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome} (${materia.turno}, ${materia.total_horas}h)`);
    }
    return reply(lines.join('\n'));
}

if (queryType === 'turnos') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) return reply(`Nao encontrei turnos cadastrados para ${aluno.aluno_nome}.`);
    const lines = header(aluno).concat('', 'Estes sao os turnos que encontrei:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome}: ${materia.turno}`);
    }
    return reply(lines.join('\n'));
}

if (queryType === 'faltas') {
    const materias = rows.filter(row => row.materia_nome);
    if (materias.length === 0) return reply(`Ainda nao encontrei frequencia cadastrada para ${aluno.aluno_nome}.`);
    const lines = header(aluno).concat('', 'Sobre faltas, encontrei o seguinte:');
    for (const materia of materias) {
        lines.push(`- ${materia.materia_nome}: ${materia.faltas_calculadas} faltas calculadas, ${materia.presencas_registradas} presencas registradas`);
    }
    lines.push('', 'So um detalhe: por enquanto eu calculo faltas usando a carga horaria menos as presencas registradas no banco.');
    return reply(lines.join('\n'));
}

return reply(header(aluno).join('\n'));
